  _onBunkerHit(cell, byEnemy) {
    const destroyed = !cell.alive;
    this.fx.particles.burst({
      position: new THREE.Vector3(cell.x, cell.y, 0),
      count: destroyed ? 10 : 5,
      colors: [0x39ff88, 0x0d3320],
      speed: [2, 6],
      gravity: -8,
      life: [0.3, 0.6],
