export class Audio {
  constructor() {
    this.ctx = null; this.master = null; this.musicGain = null;
    this.muted = false;
    this._march = { playing: false, bpm: 90, nextTime: 0, step: 0, timer: null };
    this._siren = null;
  }
  _ensure() { if (!this.ctx) { create ctx, master gain 0.5, music gain 0.35 } if (ctx.state === 'suspended') ctx.resume(); }
  _now() { return this.ctx.currentTime; }
  _env(gainNode, t, a, d, peak=1, sustain=0) — helper that builds an envelope on a gain node.
  _osc(type, freq, t0, t1, gainPeak, dest) — creates osc + gain, connects, starts, stops.
  _noise(t0, dur, filterType, f0, f1, gainPeak, dest) — noise buffer source + biquad.
  sfx(name) { switch: 'laser','enemyLaser','explosion','bigExplosion','ufoHit','powerup','playerDeath','waveClear','gameOver','shield','bomb','pickup' }
  startUfoSiren() / stopUfoSiren()
  startMarch(bpm) / stopMarch() / setMarchBpm(bpm)
  setMuted(b) { master.gain }
  suspend() { ctx.suspend() } resume() { ctx.resume() }
  dispose() { stopMarch, stopUfoSiren, ctx.close() }
}
